<div><label class="gym-label" for="{{ $prefix }}-date">Ngày tập</label><input class="gym-input" id="{{ $prefix }}-date" type="date" name="date" min="{{ now()->toDateString() }}" required></div><div><label class="gym-label" for="{{ $prefix }}-start">Giờ bắt đầu</label><input class="gym-input" id="{{ $prefix }}-start" type="time" name="start" required></div><div><label class="gym-label" for="{{ $prefix }}-end">Giờ kết thúc</label><input class="gym-input" id="{{ $prefix }}-end" type="time" name="end" required></div>
